  <script src="https://d3e54v103j8qbb.cloudfront.net/js/jquery-3.5.1.min.dc5e7f18c8.js?site=6a8c9c9e9e80d147ab2ee50a" type="text/javascript" integrity="sha256-9/aliU8dGd2tb6OSsuzixeV4y/faTqgFtohetphbbj0=" crossorigin="anonymous"></script>
  <script src="{{ asset('client-design/js/smartsoft-client-staging.js') }}" type="text/javascript"></script>
  <script>
      const isDesktop = function() {
        return window.matchMedia('(min-width: 992px)').matches
      }
      const scrollbarWidth = window.innerWidth - document.documentElement.clientWidth
      let isDesktopInitial = isDesktop()
      $(window).resize(function() {
        let newIsDesktop = window.matchMedia('(min-width: 992px)').matches;
        if (newIsDesktop !== isDesktopInitial) {
          //location.reload(); // Reload on change between desktop and tablet
        }
        isDesktopInitial = newIsDesktop;
      })
      // Disable/enable scroll
      let isScrollDisabled = false
      $('.scrollbar-space').css('width', scrollbarWidth)
      const disableScroll = function() {
        if (isDesktop()) {
          $('body').css({
            'margin-right': scrollbarWidth + 'px',
            'overflow': 'hidden'
          })
          $('.scrollbar-space').show()
        }
        isScrollDisabled = true
      }
      const enableScroll = function() {
        if (isDesktop()) {
          $('body').css({
            'margin-right': '0',
            'overflow': 'auto'
          })
          $('.scrollbar-space').hide()
        }
        isScrollDisabled = false
      }
      // Menu button
      $('.header_menu-button').click(function() {
        // Disable/enable scroll
        if (isScrollDisabled) {
          enableScroll()
          $(this).attr('aria-expanded', 'false')
        } else {
          disableScroll()
          $(this).attr('aria-expanded', 'true')
        }
      })
      // Modals
      $('[data-open-modal]').on('click', async function(e) {
        if (this.tagName === 'A') e.preventDefault();
        e.stopPropagation();
        const type = $(this).attr('data-open-modal'),
          trigger = $(this),
          modal = $('[data-modal="' + type + '"]'),
          modalInner = modal.find('.modal_inner, .modal_header'),
          modalInnerBg = modal.find('.modal_inner-bg'),
          modalCenterBg = modal.find('.modal_center-inner-bg'),
          modalBg = modal.find('.modal_bg'),
          foculables = modal.find('select, input, textarea, button, a'),
          disableFocus = $(this).is('[data-disable-focus]'),
          otherModals = $('[data-modal]:visible').not('[data-modal="' + type + '"]').length
        trigger.toggleClass('is-active')
        // Close
        if (trigger.attr('aria-expanded') === 'true') {
          trigger.attr('aria-expanded', 'false')
          foculables.attr('tabindex', '-1')
          modal.removeClass('is-opened')
          setTimeout(function() {
            modal.hide()
            if ($('[data-modal]:visible').length === 0) enableScroll()
          }, 400)
        } else { // Open
          // Close other modals
          if (otherModals > 0) {
            $('[data-open-modal][aria-expanded="true"]').each(function() {
              $(this).click();
            })
            // Pause for 400 ms
            await new Promise(resolve => setTimeout(resolve, 200))
          }
          disableScroll()
          modal.css('display', 'flex')
          setTimeout(function() {
            modal.addClass('is-opened')
          }, 100)
          setTimeout(function() {
            trigger.attr('aria-expanded', 'true')
            foculables.filter(':visible').attr('tabindex', '0')
            if (!disableFocus) foculables.filter(':visible').eq(0).focus()
          }, 400)
        }
      })
      // Dropdowns
      $('[data-open-dropdown]').on('click', async function() {
        const type = $(this).attr('data-open-dropdown'),
          dropdownTrigger = $(this),
          dropdown = $('[data-dropdown="' + type + '"]'),
          dropdownBody = dropdown.find('[data-dropdown-body]'),
          headerDropdown = $(this).attr('data-header-dropdown'),
          foculables = dropdown.find('select, input, textarea, button, a'),
          disableFocus = $(this).is('[data-disable-focus]'),
          otherDropdowns = $('[data-open-dropdown][aria-expanded="true"]').not('[data-open-dropdown="' + type + '"]').length
        dropdownTrigger.toggleClass('is-active')
        // Close
        if (dropdownTrigger.attr('aria-expanded') === 'true') {
          dropdownTrigger.attr('aria-expanded', 'false')
          foculables.attr('tabindex', '-1')
          dropdown.removeClass('is-opened')
          setTimeout(function() {
            dropdownBody.hide()
          }, 400)
        } else { // Open
          // Close other dropdowns
          if (otherDropdowns > 0) {
            $('[data-open-dropdown][aria-expanded="true"]').each(function() {
              $(this).click();
            })
            // Pause for 400 ms
            await new Promise(resolve => setTimeout(resolve, 200))
          }
          dropdownBody.show()
          setTimeout(function() {
            dropdown.addClass('is-opened')
          }, 100)
          setTimeout(function() {
            dropdownTrigger.attr('aria-expanded', 'true')
            foculables.filter(':visible').attr('tabindex', '0')
            if (!disableFocus) foculables.filter(':visible').eq(0).focus()
          }, 400)
        }
      })
      $('[data-close-modal], [data-close-dropdown]').click(function() {
        $('[data-open-modal="' + $(this).attr('data-close-modal') + '"][aria-expanded="true"]').eq(0).click()
        $('[data-open-dropdown="' + $(this).attr('data-close-dropdown') + '"][aria-expanded="true"]').eq(0).click()
      })
      // Close modal on click anywhere
      $(document).on('click', function(e) {
        const target = $(e.target);
        if ($('[data-open-modal][aria-expanded="true"]').length > 0 && !target.closest('[data-modal]').length) {
          $('[data-open-modal][aria-expanded="true"]').click();
        }
        if ($('[data-open-dropdown][aria-expanded="true"]').length > 0 && !target.closest('[data-dropdown]').length) {
          $('[data-open-dropdown][aria-expanded="true"]').click();
        }
      });
      // Allow Escape key to close modal
      $('[data-modal]').on('keydown', function(e) {
        if (e.keyCode === 27) {
          $('[data-open-modal="' + $(this).attr('data-modal') + '"]').click()
        }
      })
      // Filter selects
      $('.filter_select-trigger[data-accordion-trigger]').click(function() {
        const accordion = $(this).parent(),
          content = accordion.find('[data-accordion-content]'),
          contentInner = accordion.find('[data-accordion-content-inner]')
        if ($(this).attr('aria-expanded') === "false") {
          content.css('height', contentInner.outerHeight())
          $(this).attr('aria-expanded', 'true')
          accordion.addClass('is-active')
          accordion.siblings('.select-overlay').show()
        } else {
          content.css('height', '0')
          $(this).attr('aria-expanded', 'false')
          accordion.removeClass('is-active')
          accordion.siblings('.select-overlay').hide()
        }
      })
      $('.select-overlay').click(function() {
        $('.filter_select').find('[data-accordion-trigger][aria-expanded="true"]').click()
      })
      // Search
      $('.header_search-filter input').change(function() {
        const value = $(this).siblings('.filter_select-checkbox-label').text();
        $('[data-search-filter-value]').text(value);
        $('.header_search-filter .w-radio-input').removeClass('w--redirected-checked');
        $(this).siblings('.w-radio-input').addClass('w--redirected-checked');
        // Close select
        $('[data-search-filter-trigger]').click();
      })
      // Adaptive text area
      $('textarea').each(function() {
        $(this).on('input', function() {
          $(this).height('auto') // Reset height to auto to recalculate scrollHeight
          $(this).height(this.scrollHeight - 21) // Set the height based on the new scrollHeight
        })
      })
      // Show/hide password
      $('.password-switch').click(function() {
        const input = $(this).parents('.form_field-wrapper').find('input');
        $(this).toggleClass('is-active');
        if ($(this).hasClass('is-active')) {
          input.attr('type', 'text');
        } else {
          input.attr('type', 'password');
        }
      });
      // Button hover text
      $('.button_inner').each(function() {
        $(this).attr('data-text', $(this).find('.button_text').text())
      })
      // Switch color theme
      $('[data-switch-theme]').click(function() {
        $('body').toggleClass('light-mode');
      });
      // Expand/collapse sidebar
      $('.sidebar_collapse-button').click(function() {
        $('.sidebar, [data-collapsing]').toggleClass('is-collapsed');
      });
      // Search on mobile
      $('[data-open-search]').click(function() {
        $('.header_search-wrapper').show();
        setTimeout(function() {
          $('.header_search-wrapper').css('opacity', '1');
        }, 100);
      });
      // Close search
      $('[data-close-search]').click(function() {
        $('.header_search-wrapper').css('opacity', '0');
        setTimeout(function() {
          $('.header_search-wrapper').hide();
        }, 300);
      });
      // Tabs
      $('.tab-link').click(function() {
        const parent = $(this).parents('[data-tabs]');
        parent.find('.tab-link').removeClass('is-active');
        $(this).addClass('is-active');
        parent.find('[data-tab-pane]').hide();
        parent.find('[data-tab-pane]').eq($(this).index()).show();
      })
    </script>
